import { useEffect, useState } from 'react';
import { useSelector, useDispatch } from 'store';
import { geAllPermission } from 'store/slices/userList';
import { useParams, useNavigate } from 'react-router-dom';
import {
    Box,
    Grid,
    Stepper,
    Step,
    StepLabel,
    TextField,
    FormControlLabel,
    Switch,
    Button,
    Typography,
    Divider,
    Stack,
    FormControl,
    InputLabel,
    Select,
    MenuItem,
    Tabs,
    Tab,
    Accordion,
    AccordionSummary,
    AccordionDetails
} from '@mui/material';
import ExpandMoreIcon from '@mui/icons-material/ExpandMore';
import useSnackbar from 'hooks/useSnackbar';
import MainCard from 'ui-component/cards/MainCard';
import { useFormik } from 'formik';
import * as yup from 'yup';
import ApiRequest from 'utils/apiService';
import { useTheme } from '@mui/styles';

const steps = ['Plan Details', 'Permissions'];

const PlanPermissionForm = () => {
    const theme = useTheme();
    const { id: planId } = useParams();
    const dispatch = useDispatch();
    const { entities } = useSelector((state) => state.usersList);
    const allPermissions = entities?.permissions || [];
    const { showSnackbar } = useSnackbar();
    const navigate = useNavigate();
    const [loading, setLoading] = useState(false);
    const [activeStep, setActiveStep] = useState(0);
    const [planData, setPlanData] = useState(null);
    const [permissionsError, setPermissionsError] = useState('');
    const [tabValue, setTabValue] = useState(0);

    useEffect(() => {
        dispatch(geAllPermission({ pagination: false }));
    }, [dispatch]);

    useEffect(() => {
        if (!planId) return;
        const fetchPlanData = async () => {
            try {
                const response = await ApiRequest('GET', `/membership?id=${planId}`);
                setPlanData(response?.data || {});
            } catch (error) {
                showSnackbar(error.message, 'error');
            }
        };
        fetchPlanData();
    }, [planId]);

    // **Preserving the Correct Permission Structure**
    const structuredPermissions = allPermissions
        .filter((perm) => perm.permission_type === 'menu')
        .map((menu) => ({
            ...menu,
            enabled: planData?.permissionIds?.includes(menu.id) || false,
            children: allPermissions
                .filter((submenu) => submenu.parent_id === menu.id && submenu.permission_type === 'submenu')
                .map((submenu) => ({
                    ...submenu,
                    enabled: planData?.permissionIds?.includes(submenu.id) || false,
                    children: allPermissions
                        .filter((action) => action.parent_id === submenu.id)
                        .map((action) => ({
                            ...action,
                            enabled: planData?.permissionIds?.includes(action.id) || false
                        }))
                }))
        }));

    const formik = useFormik({
        initialValues: {
            planName: planData?.name || '',
            description: planData?.description || '',
            priceMonthly: planData?.price_monthly || '',
            priceAnnually: planData?.price_annually || '',
            position: planData?.position || '',
            accountCalculation: planData?.account_calculation || 'each_network',
            numberOfAccounts: planData?.number_of_accounts || '',
            isFeatured: planData?.is_featured ?? false,
            status: planData?.status ?? true,
            planType: planData?.plan_type || 'subscription',
            permissions: structuredPermissions
        },
        enableReinitialize: true,
        validationSchema: yup.object({
            planName: yup.string().required('Plan Name is required'),
            description: yup.string().required('Description is required'),
            priceMonthly: yup.number().required('Monthly Price is required').min(0),
            priceAnnually: yup.number().required('Annual Price is required').min(0),
            position: yup.number().required('Position is required').min(1),
            numberOfAccounts: yup.number().required('Number of Accounts is required').min(1)
        }),
        onSubmit: async (values) => {
            setLoading(true);
            try {
                const permissionIds = values.permissions
                    .flatMap((menu) => [
                        menu.enabled ? menu.id : null,
                        ...menu.children.flatMap((submenu) => [
                            submenu.enabled ? submenu.id : null,
                            ...submenu.children.map((action) => (action.enabled ? action.id : null))
                        ])
                    ])
                    .filter(Boolean);

                const uniquePermissionIds = [...new Set(permissionIds)];

                const requestData = {
                    ...values, // Spread other form values (planName, description, etc.)
                    permissionIds: uniquePermissionIds
                };

                if (planId) {
                    // ✅ Edit Case: Compare with previous permissions
                    const prevPermissionIds = planData?.permissionIds || [];

                    requestData.prevPermissionIds = prevPermissionIds;
                    requestData.permissionsToInsert = uniquePermissionIds.filter((permId) => !prevPermissionIds.includes(permId));
                    requestData.permissionsToDelete = prevPermissionIds.filter((permId) => !uniquePermissionIds.includes(permId));

                    await ApiRequest('PUT', `/membership/update/${planId}`, requestData);
                    showSnackbar('Plan updated successfully!', 'success');
                } else {
                    // ✅ Add Case: Only send enabled permissions (No need for prevPermissionIds)
                    await ApiRequest('POST', `/membership/add`, requestData);
                    showSnackbar('Plan created successfully!', 'success');
                }

                setTimeout(() => navigate('/membership/plans', { replace: true }), 1000);
            } catch (error) {
                showSnackbar(error.message, 'error');
            } finally {
                setLoading(false);
            }
        }
    });

    const handleNext = async () => {
        const errors = await formik.validateForm();
        formik.setTouched({
            planName: true,
            description: true,
            priceMonthly: true,
            priceAnnually: true
        });

        if (Object.keys(errors).length === 0) {
            setActiveStep(activeStep + 1);
        }
    };

    const handleBack = () => {
        setActiveStep(activeStep - 1);
    };

    const handlePermissionToggle = (id, level) => {
        setPermissionsError('');

        const updatedPermissions = formik.values.permissions.map((menu) => {
            if (menu.id === id) {
                // Toggle parent menu
                const isEnabled = !menu.enabled;
                return {
                    ...menu,
                    enabled: isEnabled,
                    children: menu.children.map((submenu) => ({
                        ...submenu,
                        enabled: isEnabled, // Enable all submenus when parent is enabled
                        children: submenu.children.map((action) => ({
                            ...action,
                            enabled: isEnabled // Enable all actions when parent is enabled
                        }))
                    }))
                };
            }

            return {
                ...menu,
                children: menu.children.map((submenu) => {
                    if (submenu.id === id) {
                        // Toggle submenu
                        const isEnabled = !submenu.enabled;
                        return {
                            ...submenu,
                            enabled: isEnabled,
                            children: submenu.children.map((action) => ({
                                ...action,
                                enabled: isEnabled // Enable all actions when submenu is enabled
                            }))
                        };
                    }

                    return {
                        ...submenu,
                        children: submenu.children.map((action) => {
                            if (action.id === id) {
                                // Toggle action independently (user choice)
                                return {
                                    ...action,
                                    enabled: !action.enabled
                                };
                            }
                            return action;
                        })
                    };
                })
            };
        });

        formik.setFieldValue('permissions', updatedPermissions);
    };

    return (
        <MainCard title="Manage Plan" sx={{ background: theme.palette.text.primary }}>
            <Stepper activeStep={activeStep} sx={{ pt: 3, pb: 5 }}>
                {steps.map((label) => (
                    <Step key={label}>
                        <StepLabel>{label}</StepLabel>
                    </Step>
                ))}
            </Stepper>

            {/* Step 1: Plan Details */}
            {activeStep === 0 && (
                <form>
                    <Grid container spacing={2} sx={{ mt: 2 }}>
                        <Grid item xs={12}>
                            <TextField
                                fullWidth
                                label="Plan Name"
                                {...formik.getFieldProps('planName')}
                                error={formik.touched.planName && Boolean(formik.errors.planName)}
                                helperText={formik.touched.planName && formik.errors.planName}
                                sx={{
                                    '& .MuiInputLabel-root': {
                                        color: (theme) => theme.palette.text.dark
                                    }
                                }}
                            />
                        </Grid>
                        <Grid item xs={12}>
                            <TextField
                                fullWidth
                                label="Description"
                                multiline
                                rows={4}
                                {...formik.getFieldProps('description')}
                                error={formik.touched.description && Boolean(formik.errors.description)}
                                helperText={formik.touched.description && formik.errors.description}
                                sx={{
                                    '& .MuiInputLabel-root': {
                                        color: (theme) => theme.palette.text.dark
                                    }
                                }}
                            />
                        </Grid>

                        <Grid item xs={6}>
                            <TextField
                                fullWidth
                                label="Monthly Price ($)"
                                type="number"
                                {...formik.getFieldProps('priceMonthly')}
                                error={formik.touched.priceMonthly && Boolean(formik.errors.priceMonthly)}
                                helperText={formik.touched.priceMonthly && formik.errors.priceMonthly}
                                sx={{
                                    '& .MuiInputLabel-root': {
                                        color: (theme) => theme.palette.text.dark
                                    }
                                }}
                            />
                        </Grid>
                        <Grid item xs={6}>
                            <TextField
                                fullWidth
                                label="Annual Price ($)"
                                type="number"
                                {...formik.getFieldProps('priceAnnually')}
                                error={formik.touched.priceAnnually && Boolean(formik.errors.priceAnnually)}
                                helperText={formik.touched.priceAnnually && formik.errors.priceAnnually}
                                sx={{
                                    '& .MuiInputLabel-root': {
                                        color: (theme) => theme.palette.text.dark
                                    }
                                }}
                            />
                        </Grid>
                        <Grid item xs={6} style={{ marginTop: '1rem' }}>
                            <TextField
                                fullWidth
                                label="Position"
                                type="number"
                                {...formik.getFieldProps('position')}
                                error={formik.touched.position && Boolean(formik.errors.position)}
                                helperText={formik.touched.position && formik.errors.position}
                                sx={{
                                    '& .MuiInputLabel-root': {
                                        color: (theme) => theme.palette.text.dark
                                    }
                                }}
                            />
                        </Grid>
                        <Grid item xs={6} style={{ marginTop: '1rem' }}>
                            <FormControl fullWidth>
                                <InputLabel style={{ marginTop: '-0.5rem', color: theme.palette.text.dark }}>
                                    Account Calculation
                                </InputLabel>
                                <Select {...formik.getFieldProps('accountCalculation')}>
                                    <MenuItem value="each_network">Each Network</MenuItem>
                                    <MenuItem value="entire_network">Entire Network</MenuItem>
                                </Select>
                            </FormControl>
                        </Grid>
                        <Grid item xs={6} style={{ marginTop: '1rem' }}>
                            <TextField
                                fullWidth
                                label="Number of Accounts"
                                type="number"
                                {...formik.getFieldProps('numberOfAccounts')}
                                error={formik.touched.numberOfAccounts && Boolean(formik.errors.numberOfAccounts)}
                                helperText={formik.touched.numberOfAccounts && formik.errors.numberOfAccounts}
                                sx={{
                                    '& .MuiInputLabel-root': {
                                        color: (theme) => theme.palette.text.dark
                                    }
                                }}
                            />
                        </Grid>

                        <Grid item xs={6} style={{ marginTop: '1rem' }}>
                            <FormControl fullWidth>
                                <InputLabel style={{ marginTop: '-0.5rem', color: theme.palette.text.dark }}>Plan Type</InputLabel>
                                <Select {...formik.getFieldProps('planType')}>
                                    <MenuItem value="subscription">Subscription</MenuItem>
                                    <MenuItem value="membership">Membership</MenuItem>
                                </Select>
                            </FormControl>
                        </Grid>
                        <Grid item xs={6}>
                            <FormControlLabel
                                control={
                                    <Switch
                                        checked={formik.values.isFeatured}
                                        onChange={(e) => formik.setFieldValue('isFeatured', e.target.checked)}
                                    />
                                }
                                sx={{
                                    color: theme.palette.text.dark // Change this to any color you like
                                }}
                                label="Is Featured"
                            />
                        </Grid>

                        <Grid item xs={6}>
                            <FormControlLabel
                                control={
                                    <Switch
                                        checked={formik.values.status}
                                        onChange={(e) => formik.setFieldValue('status', e.target.checked)}
                                    />
                                }
                                sx={{
                                    color: theme.palette.text.dark // Change this to any color you like
                                }}
                                label="Status"
                            />
                        </Grid>
                    </Grid>
                    <Box sx={{ mt: 2, textAlign: 'right' }}>
                        <Button variant="contained" onClick={handleNext}>
                            Next
                        </Button>
                    </Box>
                </form>
            )}

            {/* Step 2: Permissions */}
            {activeStep === 1 && (
                <Box sx={{ p: 2 }}>
                    <Tabs value={tabValue} onChange={(_, newValue) => setTabValue(newValue)} variant="scrollable">
                        {formik.values.permissions.map((menu) => (
                            <Tab key={menu.id} label={menu.label} />
                        ))}
                    </Tabs>

                    {formik.values.permissions.map((menu, index) => (
                        <div role="tabpanel" hidden={tabValue !== index} key={menu.id}>
                            {tabValue === index && (
                                <Box sx={{ p: 2, background: theme.palette.text.primary }}>
                                    <Typography variant="h6">{menu.label}</Typography>
                                    <Divider sx={{ my: 1 }} />
                                    <FormControlLabel
                                        control={<Switch checked={menu.enabled} onChange={() => handlePermissionToggle(menu.id, 'menu')} />}
                                        label={`Enable ${menu.label}`}
                                    />

                                    {menu.children.map((submenu) => (
                                        <Accordion key={submenu.id} sx={{ mt: 1, background: theme.palette.text.primary }}>
                                            <AccordionSummary expandIcon={<ExpandMoreIcon />}>
                                                <FormControlLabel
                                                    control={
                                                        <Switch
                                                            checked={submenu.enabled}
                                                            onChange={() => handlePermissionToggle(submenu.id, 'submenu')}
                                                        />
                                                    }
                                                    label={submenu.label}
                                                    sx={{ color: theme.palette.text.dark }}
                                                />
                                            </AccordionSummary>
                                            <AccordionDetails>
                                                {submenu?.children.map((action) => (
                                                    <FormControlLabel
                                                        key={action.id}
                                                        control={
                                                            <Switch
                                                                checked={action.enabled}
                                                                onChange={() => handlePermissionToggle(action.id, 'action')}
                                                            />
                                                        }
                                                        label={action.label}
                                                        sx={{ color: theme.palette.text.dark }}
                                                    />
                                                ))}
                                            </AccordionDetails>
                                        </Accordion>
                                    ))}
                                </Box>
                            )}
                        </div>
                    ))}

                    {permissionsError && <Typography color="error">{permissionsError}</Typography>}
                    <Stack direction="row" justifyContent="space-between" sx={{ mt: 2 }}>
                        <Button onClick={handleBack}>Back</Button>
                        <Button variant="contained" onClick={formik.handleSubmit}>
                            Submit
                        </Button>
                    </Stack>
                </Box>
            )}
        </MainCard>
    );
};

export default PlanPermissionForm;
